import random
import string
from typing import List

# This generator focuses on producing valid, interesting alphanumeric strings
# suitable for fields like device serials, names, and small tags used by the
# provided fuzzer stubs. It returns a bytes object; stubs will consume it
# through FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME mechanisms. We emphasize variety
# while keeping inputs valid and human-like.

ALNUM = string.ascii_letters + string.digits
HEX = string.hexdigits.lower()

# Some interesting families of strings to exercise different code paths and
# typical validations, while remaining valid C strings.
COMMON_PREFIXES = [
    "DEV", "SN", "SERIAL", "ID", "UDID", "APPLE", "USB", "MUX", "PORT", "CLIENT"
]
COMMON_SUFFIXES = [
    "A", "B", "C", "X", "Y", "Z", "00", "01", "10", "42", "9999"
]
VENDOR_MARKS = [
    "APPLE", "FOXCONN", "PEGATRON", "WISTRON", "LUXSHARE", "QUANTA"
]

# Some realistic UDID-like or serial-like patterns (still alphanumeric only)
def gen_hex(n: int, rng: random.Random) -> str:
    return ''.join(rng.choice('0123456789abcdef') for _ in range(n))

def gen_alnum(n: int, rng: random.Random) -> str:
    return ''.join(rng.choice(ALNUM) for _ in range(n))

def gen_serial_variant(rng: random.Random) -> str:
    # Produce various serial forms: prefixed, suffixed, mixed-length, hex-like, etc.
    choice = rng.randrange(8)
    if choice == 0:
        # Simple alphanumeric of moderate length
        return gen_alnum(rng.randint(8, 24), rng)
    if choice == 1:
        # UDID-like 40 hex chars
        return gen_hex(40, rng)
    if choice == 2:
        # Prefixed with vendor and year-ish code
        return f"{rng.choice(VENDOR_MARKS)}{rng.randint(2012, 2038)}-{gen_alnum(rng.randint(6,12), rng)}"
    if choice == 3:
        # With prefix and numeric run
        return f"{rng.choice(COMMON_PREFIXES)}{rng.randint(0, 999999):06d}{rng.choice(COMMON_SUFFIXES)}"
    if choice == 4:
        # Mixed hex and letters
        return gen_hex(8, rng) + gen_alnum(4, rng) + gen_hex(8, rng)
    if choice == 5:
        # Short, edge-case minimal but non-empty
        return gen_alnum(rng.randint(1, 3), rng)
    if choice == 6:
        # Near upper typical limit for serial field consumers (<=256)
        base = f"{rng.choice(COMMON_PREFIXES)}-"
        rest_len = rng.randint(50, 120)
        return base + gen_alnum(rest_len, rng)
    # choice == 7
    # Segment-like composition with delimiters removed (still alnum)
    parts = [gen_alnum(rng.randint(3, 6), rng) for _ in range(rng.randint(3, 6))]
    return ''.join(parts)

def gen_name_variant(rng: random.Random) -> str:
    choice = rng.randrange(6)
    if choice == 0:
        return "client" + gen_alnum(rng.randint(1, 8), rng)
    if choice == 1:
        return "mux" + gen_alnum(rng.randint(2, 10), rng)
    if choice == 2:
        return gen_alnum(rng.randint(4, 16), rng)
    if choice == 3:
        return f"{rng.choice(['alpha','beta','gamma','delta'])}{rng.randint(1,999)}"
    if choice == 4:
        return gen_hex(rng.randint(8, 16), rng)
    return (rng.choice(COMMON_PREFIXES) + rng.choice(COMMON_SUFFIXES))[:32]

def gen_small_tag(rng: random.Random) -> str:
    # Limited to <=32 in stub, keep it short but varied
    choice = rng.randrange(5)
    if choice == 0:
        return gen_alnum(rng.randint(3, 16), rng)
    if choice == 1:
        return gen_hex(rng.randint(4, 16), rng)
    if choice == 2:
        return rng.choice(VENDOR_MARKS)
    if choice == 3:
        return rng.choice(COMMON_PREFIXES)
    return f"T{rng.randint(0,9999):04d}"

# Compose multiple strings into one buffer separated by newlines. The fuzzer
# framework typically consumes FUZZ_PARAM_STR independently from the same seed-
# derived pool; by providing a packet with several newline-terminated strings,
# it can pull distinct pieces as needed.
# We keep total size <= 4096.

def build_buffer(rng: random.Random) -> bytes:
    lines: List[str] = []

    # Provide a sequence of candidate strings that the stubs may consume in order:
    # 1-3 serial-like strings
    for _ in range(rng.randint(1, 3)):
        lines.append(gen_serial_variant(rng))

    # 1-2 client names
    for _ in range(rng.randint(1, 2)):
        lines.append(gen_name_variant(rng))

    # Several small tags for opaque objects and clients
    for _ in range(rng.randint(2, 5)):
        lines.append(gen_small_tag(rng))

    # Add some hex-heavy and numeric-heavy extras to increase coverage
    lines.append(gen_hex(rng.randint(8, 32), rng))
    lines.append(''.join(rng.choice(string.digits) for _ in range(rng.randint(4, 12))))

    # Ensure all are ASCII alphanumeric only to comply with the data type
    # specification. Join with newlines so consumers can parse discrete strings.
    payload = '\n'.join(lines)

    # Enforce max size
    b = payload.encode('ascii', 'strict')
    if len(b) > 4096:
        b = b[:4096]
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return build_buffer(rng)

import os
import random
import string
from typing import List

# Generator for a valid filesystem path string (NUL-terminated C string when consumed via c_str())
# Constraints from stub:
# - Non-empty string
# - Reasonable length (the stub truncates >1024 chars, we keep <= 512 to be safe)
# - Should look like a directory path; include variations to exercise absolute/relative, dot components, tilde, env-like, Unicode, and edge cases
# - Return as bytes; the harness will split to FUZZ_PARAM_STR input

SEP = "/"
MAX_LEN = 512

REL_COMPONENTS = [
    "src", "bin", "lib", "etc", "var", "tmp", "opt", "data", "config", "..", ".",
    "logs", "cache", "state", "run", "share", "local", "include",
]

ABS_ROOTS = ["/", "/usr", "/usr/local", "/opt", "/var", "/etc", "/home", "/tmp"]

# Some unicode directory names to exercise UTF-8 handling
UNICODE_COMPONENTS = [
    "配置", "データ", "данные", "árvore", "späß", "测试", "δοκιμή", "datos", "módulos",
]

SPECIALS = [
    ".config", ".cache", ".local", ".ssh", ".usbmuxd", "_build", "build-debug", "build.release",
    "v1", "v2", "2026-01-01", "01_test",
]

ILLEGAL_POSIX_CHARS = set("\0")  # NUL is not allowed inside the string


def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]


def _rand_component(rng: random.Random) -> str:
    kind = rng.random()
    if kind < 0.25:
        return _rand_choice(rng, REL_COMPONENTS)
    elif kind < 0.45:
        # random ascii token
        length = rng.randint(1, 12)
        alphabet = string.ascii_letters + string.digits + "_-"
        return "".join(rng.choice(alphabet) for _ in range(length))
    elif kind < 0.65:
        return _rand_choice(rng, SPECIALS)
    elif kind < 0.9:
        return _rand_choice(rng, UNICODE_COMPONENTS)
    else:
        # dot components
        return ".." if rng.random() < 0.5 else "."


def _make_absolute_path(rng: random.Random) -> str:
    # Choose a root and append 1..6 components
    root = _rand_choice(rng, ABS_ROOTS)
    n = rng.randint(1, 6)
    comps = [_rand_component(rng) for _ in range(n)]
    path = root.rstrip(SEP) + SEP + SEP.join(c for c in comps if c)
    # sometimes add trailing slash
    if rng.random() < 0.3:
        path += SEP
    return path


def _make_relative_path(rng: random.Random) -> str:
    # build relative paths including dot segments
    n = rng.randint(1, 6)
    comps = []
    for _ in range(n):
        c = _rand_component(rng)
        comps.append(c)
    path = SEP.join(comps)
    # optionally prefix with ./ or ../ chains
    if rng.random() < 0.5:
        prefix_depth = rng.randint(0, 3)
        prefix = SEP.join([".." for _ in range(prefix_depth)])
        if prefix:
            path = prefix + (SEP + path if path else "")
        elif rng.random() < 0.5:
            path = "." + (SEP + path if path else "")
    return path


def _make_tilde_path(rng: random.Random) -> str:
    # simulate user home expansions like ~/config or ~username/.usbmuxd
    if rng.random() < 0.6:
        base = "~"
    else:
        # random username-like
        uname_len = rng.randint(1, 10)
        uname = "".join(rng.choice(string.ascii_lowercase + string.digits + "-_") for _ in range(uname_len))
        base = "~" + uname
    tail_n = rng.randint(0, 4)
    tail = SEP.join(_rand_component(rng) for _ in range(tail_n))
    return base + (SEP + tail if tail else "")


def _sanitize(path: str) -> str:
    # Remove NULs and collapse repeated slashes to keep it conventional
    path = path.replace("\x00", "")
    while "//" in path:
        path = path.replace("//", "/")
    return path


def _clip(path: str) -> str:
    if len(path) > MAX_LEN:
        return path[:MAX_LEN]
    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a style
    style = rng.random()
    if style < 0.4:
        path = _make_absolute_path(rng)
    elif style < 0.75:
        path = _make_relative_path(rng)
    else:
        path = _make_tilde_path(rng)

    # Occasionally join with environment-like tokens to exercise resolution code paths (still valid strings)
    if rng.random() < 0.25:
        token = _rand_choice(rng, ["$HOME", "${HOME}", "$TMPDIR", "$XDG_CONFIG_HOME"])  # not expanded here, just part of string
        # Insert token at front or as a component
        if rng.random() < 0.5:
            path = token + SEP + path.lstrip(SEP)
        else:
            path = path.rstrip(SEP) + SEP + token

    # Occasionally append common config directory names
    if rng.random() < 0.6:
        suffix = _rand_choice(rng, [".usbmuxd", "usbmuxd", "config", "pairing", "records"]) \
                 + ("-" + str(rng.randint(0, 9)) if rng.random() < 0.3 else "")
        if not path.endswith(SEP):
            path = path + SEP + suffix
        else:
            path = path + suffix

    path = _sanitize(path)
    path = _clip(path)

    # Ensure non-empty
    if not path:
        path = "/tmp"

    # Return as bytes (UTF-8). The fuzzer stub uses std::string::c_str(), providing NUL-termination on the C++ side.
    return path.encode("utf-8")
